<script>
  import { onMount } from 'svelte'
  import { apiGet,apiPost } from './api.js'
  import { activeTenant,tenants } from './tenantStore.js'
  import { canOperate } from './cockpit.js'
  import { fmtDateTime,ageLabel } from './product.js'
  let jobs=$state([]),sources=$state([]),error=$state(''),busy=$state(false),filter=$state('all'),changing=$state(false)
  const labels={queued:'Wartet',running:'Läuft',retry:'Wiederholung geplant',done:'Abgeschlossen',partial:'Teilweise',failed:'Fehlgeschlagen',cancelled:'Abgebrochen',interrupted:'Unterbrochen',ok:'Aktuell',error:'Fehler',blocked:'Rechte / Lizenz prüfen',never:'Noch nie gelaufen'}
  let shown=$derived(jobs.filter(j=>!$activeTenant||j.tenantId===$activeTenant.id).filter(j=>filter==='all'||(filter==='active'?['queued','running','retry'].includes(j.queueState):['failed','partial','interrupted'].includes(j.queueState))))
  async function loadSync(id){try{const r=await apiGet(`/api/tenants/${encodeURIComponent(id)}/sync`);if(id===$activeTenant?.id)sources=r.sources}catch(e){error=e.message}}
  async function load(){if(busy)return;busy=true;error='';try{jobs=(await apiGet('/api/platform/jobs')).jobs;if($activeTenant)await loadSync($activeTenant.id)}catch(e){error=e.message}finally{busy=false}}
  async function action(j,kind){changing=true;error='';try{await apiPost(`/api/platform/jobs/${encodeURIComponent(j.id)}/${kind}`);await load()}catch(e){error=e.message}finally{changing=false}}
  $effect(()=>{const id=$activeTenant?.id;sources=[];if(id)loadSync(id)})
  onMount(()=>{load();const t=setInterval(load,5000);return()=>clearInterval(t)})
</script>
<div class="cp-head"><div><h2>Jobs & Synchronisierung</h2><p>Dauerhafte Warteschlange · {$activeTenant?.name||'Alle zugewiesenen Mandanten'}</p></div><button class="btn btn-secondary" disabled={busy} onclick={load}>Aktualisieren</button></div>
<div class="cp-note">Monitoring-Läufe werden nach einem Worker-Abbruch kontrolliert wieder aufgenommen. Schreibende Alt-Jobs bleiben nach einem Neustart als unterbrochen sichtbar und werden nicht automatisch wiederholt.</div>
{#if error}<div class="cp-note cp-gaps" role="alert">{error}</div>{/if}
<div class="cp-tabs">{#each [['all','Alle Läufe'],['active','Aktiv / Wartend'],['errors','Handlungsbedarf']] as [key,label]}<button class:active={filter===key} onclick={()=>filter=key}>{label}</button>{/each}</div>
<div class="cp-table-wrap"><table><thead><tr><th>Mandant / Lauf</th><th>Status</th><th>Fortschritt</th><th>Versuche</th><th>Angefordert</th><th>Aktion</th></tr></thead><tbody>{#each shown as j}<tr><td>{j.tenantName||$tenants.find(t=>t.id===j.tenantId)?.name||j.tenantId}<small>{j.kind==='managed'?'Monitoring-Sync':'Fachmodul-Job'} · {j.id}</small></td><td><span class="cp-badge" class:ok={j.queueState==='done'} class:high={['failed','partial','interrupted'].includes(j.queueState)}>{labels[j.queueState]||j.queueState}</span></td><td style="white-space:normal;max-width:310px">{j.phase}<small>{j.error||j.hint||''}</small>{#if j.queueState==='retry'}<small>Nächster Versuch {fmtDateTime(j.nextAttemptAt)}</small>{/if}</td><td>{j.attempts}/{j.maxAttempts}</td><td>{fmtDateTime(j.createdAt)}<small>{j.requestedBy}</small></td><td>{#if j.kind==='managed'&&canOperate($tenants.find(t=>t.id===j.tenantId))}{#if ['failed','partial','interrupted'].includes(j.queueState)}<button class="btn btn-secondary" disabled={changing} onclick={()=>action(j,'retry')}>Wiederholen</button>{:else if ['queued','retry'].includes(j.queueState)}<button class="btn btn-secondary" disabled={changing} onclick={()=>action(j,'cancel')}>Abbrechen</button>{/if}{/if}</td></tr>{:else}<tr><td colspan="6">Keine Läufe in dieser Ansicht.</td></tr>{/each}</tbody></table></div>
{#if $activeTenant}<section class="cp-panel" style="margin-top:22px"><h3>Sync-Zustand je Datenquelle</h3><div class="cp-table-wrap" style="margin-top:16px"><table><thead><tr><th>Quelle</th><th>Status</th><th>Letzter Erfolg</th><th>Nächster Lauf</th><th>Fehlerfolge</th></tr></thead><tbody>{#each sources as s}<tr><td>{s.label}</td><td>{labels[s.status]||s.status}{#if s.freshness==='stale'} · veraltet{/if}<small style="max-width:380px;white-space:normal">{s.error||''}</small></td><td>{fmtDateTime(s.success_at)}<small>{s.success_at?ageLabel(s.success_at):'Keine erfolgreichen Daten'}</small></td><td>{fmtDateTime(s.next_at)}</td><td>{s.failures||0}</td></tr>{/each}</tbody></table></div></section>{/if}
